		const visibleGuidedCanvasMarkerPoint = async (testId, label) => {
			const marker = page.getByTestId(testId);
			try {
				await marker.waitFor({ state: "visible", timeout: 10_000 });
			} catch (error) {
				const details = await page.evaluate(
					(id) => ({
						marker: document.querySelector(`[data-testid="${id}"]`)?.outerHTML ?? null,
						activity:
							document
								.querySelector('[data-testid="tilefab-app"]')
								?.getAttribute("data-editor-activity") ?? null,
						tool:
							document
								.querySelector('[data-testid="tilefab-app"]')
								?.getAttribute("data-editor-tool") ?? null,
						guidedTarget:
							document
								.querySelector('[data-testid="tilefab-app"]')
								?.getAttribute("data-guided-primary-target") ?? null,
						guidedScoped:
							document
								.querySelector('[data-testid="tilefab-app"]')
								?.getAttribute("data-guided-build-scoped") ?? null,
						railSelectionCoach:
							document
								.querySelector('[data-testid="tilefab-app"]')
								?.getAttribute("data-guided-rail-selection-coach") ?? null,
						selectedModule:
							document
								.querySelector('[data-testid="rail-canvas"]')
								?.getAttribute("data-selected-module-id") ?? null,
						areaSelectionModules:
							document
								.querySelector('[data-testid="tilefab-app"]')
								?.getAttribute("data-area-selection-modules") ?? null,
						suggestedAction:
							document.querySelector('[data-testid="guided-build-suggested-action"]')
								?.textContent ?? null,
						guidedMission:
							document
								.querySelector('[data-testid="guided-build-panel"]')
								?.getAttribute("data-current-mission") ?? null,
						placementCoach:
							document
								.querySelector('[data-testid="tilefab-app"]')
								?.getAttribute("data-guided-organization-placement") ?? null,
						rendererMarkers:
							document
								.querySelector('[data-testid="rail-canvas"]')
								?.getAttribute("data-guided-canvas-markers") ?? null,
						previewState:
							document
								.querySelector('[data-testid="rail-canvas"]')
								?.getAttribute("data-organization-bundle-preview-state") ?? null,
						previewAnchor:
							document
								.querySelector('[data-testid="rail-canvas"]')
								?.getAttribute("data-organization-bundle-preview-anchor") ?? null,
						previewSourceBounds:
							document
								.querySelector('[data-testid="rail-canvas"]')
								?.getAttribute("data-organization-bundle-source-bounds") ?? null,
					}),
					testId,
				);
				throw new Error(`${label} did not become visible: ${JSON.stringify(details)}.`, {
					cause: error,
				});
			}
			const box = await marker.boundingBox();
			if (!box) throw new Error(`${label} has no visible bounding box.`);
			if (testId === "guided-rail-selection-target") {
				assertAtLeast(box.width, 44, `${label} width`);
				assertAtLeast(box.height, 44, `${label} height`);
			}
			assertAtLeast(box.x, 0, `${label} left viewport bound`);
			assertAtLeast(box.y, 0, `${label} top viewport bound`);
			assertAtMost(
				box.x + box.width,
				page.viewportSize()?.width ?? 0,
				`${label} right viewport bound`,
			);
			assertAtMost(
				box.y + box.height,
				page.viewportSize()?.height ?? 0,
				`${label} bottom viewport bound`,
			);
			const point = { x: box.x + box.width / 2, y: box.y + box.height / 2 };
			const markerIsButton = await marker.evaluate((element) => element.tagName === "BUTTON");
			assertEqual(
				await page.evaluate(
					({ x, y, expectedTestId }) =>
						document.elementFromPoint(x, y)?.getAttribute("data-testid") === expectedTestId,
					{
						...point,
						expectedTestId: markerIsButton ? testId : "rail-canvas",
					},
				),
				true,
				`${label} remains the topmost visible action over the Canvas`,
			);
			return point;
		};

		await activateGuidedEquipmentTarget(page, "ohb", "Guided OHB");
