async function assertLocatorOwnsHitArea(locator, label) {
	const result = await locator.evaluate((element) => {
		const bounds = element.getBoundingClientRect();
		const inset = Math.min(4, bounds.width / 4, bounds.height / 4);
		const points = [
			[bounds.left + bounds.width / 2, bounds.top + bounds.height / 2],
			[bounds.left + inset, bounds.top + inset],
			[bounds.right - inset, bounds.top + inset],
			[bounds.left + inset, bounds.bottom - inset],
			[bounds.right - inset, bounds.bottom - inset],
		];
		return {
			bounds: {
				left: bounds.left,
				top: bounds.top,
				right: bounds.right,
				bottom: bounds.bottom,
			},
			owned: points.map(([x, y]) => element.contains(document.elementFromPoint(x, y))),
		};
	});
	assertEqual(
		result.owned.every(Boolean),
		true,
		`${label} owns center and corner hit targets ${JSON.stringify(result)}`,
	);
}

async function locatorsOverlap(firstLocator, secondLocator) {
	const [first, second] = await Promise.all([
		firstLocator.boundingBox(),
		secondLocator.boundingBox(),
	]);
	if (!first || !second) {
		throw new Error(`Cannot compare hidden locator bounds: ${JSON.stringify({ first, second })}`);
	}
	return (
		first.x < second.x + second.width &&
		first.x + first.width > second.x &&
		first.y < second.y + second.height &&
		first.y + first.height > second.y
	);
}

async function assertRaisedCompactInspectorCanvasOwnership(page, inspectorTestId, label) {
	const before = await readMetrics(page);
	await activateEditorActivity(page, "build");
	await page.waitForFunction(
		(expectedInspectorTestId) =>
			document.querySelector('[data-testid="editor-action-hints"]')?.getAttribute("data-raised") ===
				"true" &&
			document.querySelector('[data-testid="rail-buildbar"]') !== null &&
			document.querySelector(`[data-testid="${expectedInspectorTestId}"]`) !== null,
		inspectorTestId,
		{ timeout: 10_000 },
	);
	await page.evaluate(
		() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
	);
	const ownership = await page.evaluate((expectedInspectorTestId) => {
		const inspector = document.querySelector(`[data-testid="${expectedInspectorTestId}"]`);
		const tools = document.querySelector(".tilefab-tools");
		const canvas = document.querySelector('[data-testid="rail-canvas"]');
		if (!(inspector instanceof HTMLElement) || !(tools instanceof HTMLElement) || !canvas) {
			return null;
		}
		const sheet = inspector.getBoundingClientRect();
		const rail = tools.getBoundingClientRect();
		const canvasRect = canvas.getBoundingClientRect();
		const safe = {
			left: Math.max(sheet.left, rail.right + 6),
			right: canvasRect.right - 10,
			top: canvasRect.top + 12,
			bottom: sheet.top - 8,
		};
		const hitX = safe.left + (safe.right - safe.left) / 2;
		const hitY = safe.top + (safe.bottom - safe.top) / 2;
		return {
			sheetHeight: sheet.height,
			safeWidth: safe.right - safe.left,
			safeHeight: safe.bottom - safe.top,
			hitIsCanvas: document.elementFromPoint(hitX, hitY) === canvas,
		};
	}, inspectorTestId);
	if (!ownership) throw new Error(`${label} raised compact ownership geometry is unavailable.`);
	assertAtMost(ownership.sheetHeight, 148, `${label} raised Inspector height budget`);
	assertAtLeast(ownership.safeWidth, 300, `${label} raised Canvas width`);
	assertAtLeast(ownership.safeHeight, 128, `${label} raised Canvas height`);
	assertEqual(ownership.hitIsCanvas, true, `${label} raised Canvas owns pointer hit`);
	await assertFittedMapVisible(page);
	assertExactStaticFabModelIdentity(
		await readMetrics(page),
		before,
		`${label} retained Fit isolation`,
	);
	await page.locator('button[aria-label="전체 보기"]').evaluate((element) => element.click());
	await page.waitForTimeout(100);
	await assertFittedMapVisible(page);
	assertExactStaticFabModelIdentity(
		await readMetrics(page),
		before,
		`${label} manual Fit isolation`,
	);
	const loopConnect = page.getByRole("button", { name: /LOOP CONNECT/ });
	await loopConnect.waitFor({ state: "visible", timeout: 10_000 });
	await loopConnect.click();
	await page.waitForFunction(
		() =>
			document.querySelector('[data-testid="rail-buildbar"]')?.getAttribute("data-catalog-id") ===
			"network-link",
		undefined,
		{ timeout: 10_000 },
	);
	await page.evaluate(
		() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
	);
	const networkOwnership = await page.evaluate((expectedInspectorTestId) => {
		const inspector = document.querySelector(`[data-testid="${expectedInspectorTestId}"]`);
		const hints = document.querySelector(
			'[data-testid="editor-action-hints"][data-context="selection"][data-raised="true"]',
		);
		const canvas = document.querySelector('[data-testid="rail-canvas"]');
		if (!(inspector instanceof HTMLElement) || !(hints instanceof HTMLElement) || !canvas) {
			return null;
		}
		const sheet = inspector.getBoundingClientRect();
		const hintBounds = hints.getBoundingClientRect();
		const canvasBounds = canvas.getBoundingClientRect();
		return {
			gap: hintBounds.top - sheet.bottom,
			safeHeight: sheet.top - 8 - (canvasBounds.top + 12),
		};
	}, inspectorTestId);
	if (!networkOwnership) throw new Error(`${label} Network Link ownership is unavailable.`);
	assertAtLeast(networkOwnership.gap, 10, `${label} Network Link hints clear Inspector`);
	assertAtLeast(networkOwnership.safeHeight, 128, `${label} Network Link Canvas height`);
	const networkInspector = page.getByTestId(inspectorTestId);
	const networkDisclosure = networkInspector.getByTestId("compact-inspector-disclosure");
	const networkClose = networkInspector.locator(".tilefab-inspector-close");
	await assertLocatorOwnsHitArea(networkDisclosure, `${label} Network Link expanded disclosure`);
	await assertLocatorOwnsHitArea(networkClose, `${label} Network Link expanded close`);
	await networkDisclosure.click();
	assertEqual(
		await networkInspector.getAttribute("data-compact-snap"),
		"peek",
		`${label} Network Link peek identity`,
	);
	await assertLocatorOwnsHitArea(networkDisclosure, `${label} Network Link peek disclosure`);
	await assertLocatorOwnsHitArea(networkClose, `${label} Network Link peek close`);
	await networkDisclosure.click();
	await page.getByRole("button", { name: "SMART ROUTE", exact: true }).click();
	await page.waitForFunction(
		() =>
			document.querySelector('[data-testid="rail-buildbar"]')?.getAttribute("data-catalog-id") ===
			"route",
		undefined,
		{ timeout: 10_000 },
	);
	assertExactStaticFabModelIdentity(
		await readMetrics(page),
		before,
		`${label} Network Link presentation isolation`,
	);
	await activateEditorActivity(page, "inspect");
	await page.waitForFunction(
		() =>
			document.querySelector('[data-testid="editor-action-hints"]')?.getAttribute("data-raised") ===
			"false",
		undefined,
		{ timeout: 10_000 },
	);
}

async function assertCompactContextualInspectorSheet(page, inspectorTestId, label) {
	const inspector = page.getByTestId(inspectorTestId);
	await inspector.waitFor({ state: "visible" });
	assertEqual(
		await inspector.getAttribute("data-compact-layout"),
		"bottom-sheet",
		`${label} compact presentation`,
	);
	assertEqual(
		await inspector.getAttribute("data-compact-snap"),
		"expanded",
		`${label} first selection starts expanded`,
	);
	assertEqual(
		await inspector.evaluate((element) =>
			Number(
				element.matches('[role="dialog"], [aria-modal="true"]') ||
					element.querySelector('[role="dialog"], [aria-modal="true"]') !== null,
			),
		),
		0,
		`${label} remains a non-modal selection region`,
	);
	const disclosure = inspector.getByTestId("compact-inspector-disclosure");
	const close = inspector.locator(".tilefab-inspector-close");
	const contentId = await disclosure.getAttribute("aria-controls");
	if (!contentId) throw new Error(`${label} disclosure does not name its controlled body.`);
	const content = inspector.locator(`#${contentId}`);
	assertEqual(await content.count(), 1, `${label} disclosure controls exactly one body`);
	assertEqual(
		await disclosure.getAttribute("aria-label"),
		"선택 세부정보",
		`${label} stable disclosure name`,
	);
	assertEqual(
		await disclosure.getAttribute("aria-expanded"),
		"true",
		`${label} expanded semantics`,
	);
	assertIncludes(await disclosure.innerText(), "접기", `${label} expanded visible action copy`);

	const expandedLayout = await page.evaluate((expectedInspectorTestId) => {
		const inspectorElement = document.querySelector(`[data-testid="${expectedInspectorTestId}"]`);
		const tools = document.querySelector(".tilefab-tools");
		const hints = document.querySelector('[data-testid="editor-action-hints"]');
		const canvas = document.querySelector('[data-testid="rail-canvas"]');
		const recovery = document.querySelector(".tilefab-recovery");
		if (!inspectorElement || !tools || !canvas) return null;
		const inspectorRect = inspectorElement.getBoundingClientRect();
		const toolsRect = tools.getBoundingClientRect();
		const hintsRect = hints?.getBoundingClientRect() ?? null;
		const canvasRect = canvas.getBoundingClientRect();
		const safeRect = {
			left: Math.max(inspectorRect.left, toolsRect.right + 6),
			right: canvasRect.right - 10,
			top: canvasRect.top + 12,
			bottom: inspectorRect.top - 8,
		};
		const hitX = safeRect.left + (safeRect.right - safeRect.left) / 2;
		const hitY = safeRect.top + (safeRect.bottom - safeRect.top) / 2;
		return {
			viewportWidth: window.innerWidth,
			inspector: {
				left: inspectorRect.left,
				right: inspectorRect.right,
				top: inspectorRect.top,
				bottom: inspectorRect.bottom,
				height: inspectorRect.height,
			},
			toolsRight: toolsRect.right,
			hintsTop: hintsRect?.top ?? Number.POSITIVE_INFINITY,
			safeWidth: safeRect.right - safeRect.left,
			safeHeight: safeRect.bottom - safeRect.top,
			safeHitIsCanvas: document.elementFromPoint(hitX, hitY) === canvas,
			horizontalOverflow: document.documentElement.scrollWidth - window.innerWidth,
			recoveryVisible:
				recovery instanceof HTMLElement &&
				recovery.offsetParent !== null &&
				getComputedStyle(recovery).visibility !== "hidden",
		};
	}, inspectorTestId);
	if (!expandedLayout) throw new Error(`${label} compact geometry is unavailable.`);
	assertAtLeast(expandedLayout.inspector.left, 72, `${label} compact rail safe edge`);
	assertAtMost(
		expandedLayout.inspector.right,
		expandedLayout.viewportWidth - 10,
		`${label} right viewport edge`,
	);
	assertAtMost(
		expandedLayout.toolsRight,
		expandedLayout.inspector.left,
		`${label} clears Activity Rail`,
	);
	assertAtMost(
		expandedLayout.inspector.bottom,
		expandedLayout.hintsTop,
		`${label} clears action hints`,
	);
	assertAtLeast(expandedLayout.safeWidth, 300, `${label} usable Canvas width above sheet`);
	assertAtLeast(expandedLayout.safeHeight, 180, `${label} usable Canvas height above sheet`);
	assertEqual(expandedLayout.safeHitIsCanvas, true, `${label} usable Canvas owns pointer hit`);
	assertEqual(expandedLayout.horizontalOverflow, 0, `${label} horizontal overflow`);
	assertEqual(expandedLayout.recoveryVisible, false, `${label} recovery cannot intercept sheet`);
	for (const [target, targetLabel] of [
		[disclosure, "disclosure"],
		[close, "close"],
	]) {
		const bounds = await target.boundingBox();
		if (!bounds) throw new Error(`${label} ${targetLabel} bounds are unavailable.`);
		assertAtLeast(bounds.width, 44, `${label} ${targetLabel} target width`);
		assertAtLeast(bounds.height, 44, `${label} ${targetLabel} target height`);
		await assertLocatorOwnsHitArea(target, `${label} ${targetLabel}`);
	}

	const before = await readMetrics(page);
	await disclosure.focus();
	await disclosure.press("Enter");
	await page.waitForFunction(
		(expectedTestId) => {
			const element = document.querySelector(`[data-testid="${expectedTestId}"]`);
			return element instanceof HTMLElement && element.getBoundingClientRect().height <= 64.5;
		},
		inspectorTestId,
		{ timeout: 2_000 },
	);
	assertEqual(await disclosure.getAttribute("aria-expanded"), "false", `${label} Enter peeks`);
	assertIncludes(await disclosure.innerText(), "열기", `${label} peek visible recovery action`);
	assertEqual(await inspector.getAttribute("data-compact-snap"), "peek", `${label} peek identity`);
	assertEqual(await content.getAttribute("hidden"), "", `${label} peek hides body`);
	assertEqual(
		await content
			.locator('button, a[href], input, select, textarea, summary, [tabindex]:not([tabindex="-1"])')
			.evaluateAll(
				(elements) => elements.filter((element) => element.offsetParent !== null).length,
			),
		0,
		`${label} peek removes body controls from Tab order`,
	);
	assertEqual(
		await disclosure.evaluate((element) => document.activeElement === element),
		true,
		`${label} Enter retains disclosure focus`,
	);
	const peekHeight = (await inspector.boundingBox())?.height ?? 0;
	assertAtLeast(peekHeight, 56, `${label} peek minimum height`);
	assertAtMost(peekHeight, 64, `${label} peek maximum height`);
	await assertLocatorOwnsHitArea(disclosure, `${label} peek disclosure`);
	await assertLocatorOwnsHitArea(close, `${label} peek close`);
	assertExactStaticFabModelIdentity(
		await readMetrics(page),
		before,
		`${label} Enter peek isolation`,
	);

	await disclosure.press("Space");
	await page.waitForFunction(
		(expectedTestId) => {
			const element = document.querySelector(`[data-testid="${expectedTestId}"]`);
			return element instanceof HTMLElement && element.getBoundingClientRect().height > 64.5;
		},
		inspectorTestId,
		{ timeout: 2_000 },
	);
	assertEqual(await disclosure.getAttribute("aria-expanded"), "true", `${label} Space expands`);
	assertIncludes(await disclosure.innerText(), "접기", `${label} re-expanded visible action copy`);
	assertEqual(
		await disclosure.evaluate((element) => document.activeElement === element),
		true,
		`${label} Space retains disclosure focus`,
	);
	await disclosure.click();
	assertEqual(await inspector.getAttribute("data-compact-snap"), "peek", `${label} pointer peeks`);
	await disclosure.click();
	assertEqual(
		await inspector.getAttribute("data-compact-snap"),
		"expanded",
		`${label} pointer expands`,
	);
	assertExactStaticFabModelIdentity(
		await readMetrics(page),
		before,
		`${label} disclosure isolation`,
	);

	await page.locator('button[aria-label="전체 보기"]').evaluate((element) => element.click());
	await page.waitForTimeout(100);
	await assertFittedMapVisible(page);
	assertExactStaticFabModelIdentity(
		await readMetrics(page),
		before,
		`${label} compact Fit isolation`,
	);
	if (inspectorTestId === "rail-inspector") {
		await assertRaisedCompactInspectorCanvasOwnership(
			page,
			inspectorTestId,
			`${label} 390x844 Inspect to Build`,
		);
	}

	await disclosure.focus();
	await disclosure.press("Enter");
	await page.waitForFunction(
		(expectedTestId) =>
			document
				.querySelector(`[data-testid="${expectedTestId}"]`)
				?.getAttribute("data-compact-snap") === "peek",
		inspectorTestId,
		{ timeout: 2_000 },
	);

	await page.setViewportSize({ width: 431, height: 844 });
	await page.evaluate(
		() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
	);
	await page.waitForFunction(
		(expectedTestId) => {
			const element = document.querySelector(`[data-testid="${expectedTestId}"]`);
			return (
				element?.getAttribute("data-compact-layout") === "side-panel" &&
				element.getAttribute("data-compact-snap") === "expanded"
			);
		},
		inspectorTestId,
		{ timeout: 2_000 },
	);
	const cliffLayout = await inspector.evaluate((element) => {
		const sheet = element.getBoundingClientRect();
		const tools = document.querySelector(".tilefab-tools")?.getBoundingClientRect();
		return {
			presentation: element.getAttribute("data-compact-layout"),
			disclosureCount: element.querySelectorAll('[data-testid="compact-inspector-disclosure"]')
				.length,
			density: document.querySelector(".tilefab-tools")?.getAttribute("data-tool-density"),
			canvasLane: tools ? sheet.left - tools.right : 0,
		};
	});
	assertEqual(cliffLayout.presentation, "side-panel", `${label} 431px side presentation`);
	assertEqual(cliffLayout.disclosureCount, 0, `${label} 431px omits compact disclosure`);
	assertEqual(cliffLayout.density, "compact", `${label} 431px collision density`);
	assertAtLeast(cliffLayout.canvasLane, 96, `${label} 431px selectable Canvas lane`);
	assertEqual(
		await close.evaluate((element) => document.activeElement === element),
		true,
		`${label} 431px disclosure focus hands off to close`,
	);
	const wideBodyControl = content
		.locator(
			"button:not([disabled]), a[href], input:not([disabled]), select:not([disabled]), summary",
		)
		.first();
	await wideBodyControl.focus();
	assertEqual(
		await wideBodyControl.evaluate((element) => document.activeElement === element),
		true,
		`${label} 431px body control receives focus`,
	);

	await page.setViewportSize({ width: 390, height: 720 });
	await page.evaluate(
		() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
	);
	const shortDisclosure = inspector.getByTestId("compact-inspector-disclosure");
	const shortClose = inspector.locator(".tilefab-inspector-close");
	assertEqual(
		await inspector.getAttribute("data-compact-snap"),
		"expanded",
		`${label} 390px return resets to expanded`,
	);
	assertEqual(
		await content.getAttribute("hidden"),
		null,
		`${label} 390px return keeps body visible`,
	);
	assertEqual(
		await wideBodyControl.evaluate((element) => document.activeElement === element),
		true,
		`${label} 390px return does not hide focused body control`,
	);
	await assertLocatorOwnsHitArea(shortDisclosure, `${label} 390x720 disclosure`);
	await assertLocatorOwnsHitArea(shortClose, `${label} 390x720 close`);
	assertEqual(
		await page
			.locator(".tilefab-recovery")
			.evaluateAll((elements) =>
				elements.some(
					(element) =>
						element.offsetParent !== null && getComputedStyle(element).visibility !== "hidden",
				),
			),
		false,
		`${label} 390x720 recovery interception`,
	);
	if (inspectorTestId === "rail-inspector") {
		await assertRaisedCompactInspectorCanvasOwnership(
			page,
			inspectorTestId,
			`${label} 390x720 Inspect to Build`,
		);
	}

	await page.setViewportSize({ width: 390, height: 844 });
	await page.evaluate(
		() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
	);
}

function legacyBuildbarButton(page, accessibleName) {
	return accessibleName === "ASSEMBLE"
		? page.getByTestId("rail-pattern-browser-toggle")
		: page.getByRole("button", { name: accessibleName });
}

async function assertEditorActivityRailLayout(page, label) {
	const activities = ["build", "assemble", "equip", "inspect"];
	const app = page.getByTestId("tilefab-app");
	const activeActivity = await app.getAttribute("data-editor-activity");
	let pressedCount = 0;
	let previousTop = Number.NEGATIVE_INFINITY;
	for (const activity of activities) {
		const testId = `editor-activity-${activity}`;
		const button = page.getByTestId(testId);
		await assertLocatorInsideViewport(page, button);
		const bounds = await button.boundingBox();
		if (!bounds) throw new Error(`${label} ${activity} activity has no layout bounds.`);
		assertAtLeast(bounds.width, 44, `${label} ${activity} activity target width`);
		assertAtLeast(bounds.height, 44, `${label} ${activity} activity target height`);
		if (bounds.y <= previousTop) {
			throw new Error(`${label} activity visual order is not Build → Assemble → Equip → Inspect.`);
		}
		previousTop = bounds.y;
		assertEqual(
			await page.evaluate(
				({ x, y, expectedTestId }) =>
					document
						.elementFromPoint(x, y)
						?.closest(`[data-testid="${expectedTestId}"]`)
						?.getAttribute("data-testid") === expectedTestId,
				{
					x: bounds.x + bounds.width / 2,
					y: bounds.y + bounds.height / 2,
					expectedTestId: testId,
				},
			),
			true,
			`${label} ${activity} activity center hit target`,
		);
		const visibleLabel = await button.locator("strong").evaluate((element) => {
			const labelBounds = element.getBoundingClientRect();
			const buttonBounds = element.closest("button")?.getBoundingClientRect();
			return {
				text: element.textContent?.trim() ?? "",
				inside:
					buttonBounds !== undefined &&
					labelBounds.left >= buttonBounds.left - 0.5 &&
					labelBounds.right <= buttonBounds.right + 0.5,
			};
		});
		assertEqual(visibleLabel.text, activity.toUpperCase(), `${label} ${activity} visible label`);
		assertEqual(visibleLabel.inside, true, `${label} ${activity} visible label clipping`);
		const pressed = (await button.getAttribute("aria-pressed")) === "true";
		if (pressed) pressedCount += 1;
		assertEqual(pressed, activity === activeActivity, `${label} ${activity} pressed identity`);
	}
	assertEqual(pressedCount, 1, `${label} single active editor activity`);
}

async function assertLocatorInsideViewport(page, locator) {
	const box = await locator.boundingBox();
	const viewport = page.viewportSize();
	const visibility = await locator.evaluate((element) => {
		const rect = element.getBoundingClientRect();
		const clippingAncestors = [];
		let left = Math.max(0, rect.left);
		let top = Math.max(0, rect.top);
		let right = Math.min(window.innerWidth, rect.right);
		let bottom = Math.min(window.innerHeight, rect.bottom);
		for (let parent = element.parentElement; parent; parent = parent.parentElement) {
			const style = getComputedStyle(parent);
			const parentRect = parent.getBoundingClientRect();
			if (style.overflowX !== "visible") {
				left = Math.max(left, parentRect.left);
				right = Math.min(right, parentRect.right);
			}
			if (style.overflowY !== "visible") {
				top = Math.max(top, parentRect.top);
				bottom = Math.min(bottom, parentRect.bottom);
			}
			if (style.overflowX !== "visible" || style.overflowY !== "visible") {
				clippingAncestors.push({
					className: parent.className,
					height: parentRect.height,
					overflowX: style.overflowX,
					overflowY: style.overflowY,
				});
			}
		}
		const centerX = rect.left + rect.width / 2;
		const centerY = rect.top + rect.height / 2;
		const hit = document.elementFromPoint(centerX, centerY);
		return {
			visibleWidth: Math.max(0, right - left),
			visibleHeight: Math.max(0, bottom - top),
			width: rect.width,
			height: rect.height,
			hitTarget: hit !== null && element.contains(hit),
			hitElement:
				hit === null
					? null
					: {
							tagName: hit.tagName,
							className: hit.getAttribute("class") ?? "",
							testId: hit.getAttribute("data-testid") ?? "",
							label: hit.getAttribute("aria-label") ?? hit.textContent?.trim().slice(0, 80) ?? "",
						},
			label:
				element.getAttribute("aria-label") ?? element.getAttribute("title") ?? element.textContent,
			parentLabel: element.parentElement?.getAttribute("aria-label") ?? "",
			clippingAncestors,
		};
	});
	if (
		!box ||
		!viewport ||
		box.x < 0 ||
		box.y < 0 ||
		box.x + box.width > viewport.width ||
		box.y + box.height > viewport.height ||
		visibility.visibleWidth < visibility.width - 1 ||
		visibility.visibleHeight < visibility.height - 1 ||
		!visibility.hitTarget
	) {
		throw new Error(
			`Active control is clipped or occluded: ${JSON.stringify({ box, viewport, visibility })}.`,
		);
	}
}

async function assertOrdinaryPortToolDensity(
	page,
	viewport,
	label,
	{ exerciseToggle = false } = {},
) {
	const shouldAutoCompact = viewport.width <= 520;
	const expectedDensity = shouldAutoCompact ? "compact" : "expanded";
	const expectedContext = shouldAutoCompact ? "ordinary-port" : "default";
	await page.waitForFunction(
		({ density, context }) => {
			const tools = document.querySelector(".tilefab-tools");
			return (
				tools?.getAttribute("data-tool-density") === density &&
				tools.getAttribute("data-tool-density-context") === context
			);
		},
		{ density: expectedDensity, context: expectedContext },
		{ timeout: 10_000 },
	);
	const activityNavigation = page.locator(".tilefab-tools");
	const densityToggle = page.getByTestId("editor-tool-description-toggle");
	assertEqual(
		await activityNavigation.getAttribute("data-tool-density-preference"),
		"expanded",
		`${label} preserves the global expanded preference`,
	);
	assertEqual(
		await activityNavigation.getAttribute("data-tool-density-constrained"),
		"false",
		`${label} ordinary Port density remains a soft choice`,
	);
	assertEqual(
		await densityToggle.getAttribute("aria-disabled"),
		null,
		`${label} density toggle remains enabled`,
	);
	assertEqual(
		await densityToggle.getAttribute("aria-pressed"),
		shouldAutoCompact ? "false" : "true",
		`${label} density toggle announces the effective state`,
	);
	if (shouldAutoCompact) {
		assertEqual(
			await densityToggle.getAttribute("aria-describedby"),
			"tilefab-port-tool-density-context",
			`${label} compact density explains its task-local owner`,
		);
		assertIncludes(
			(await page.locator("#tilefab-port-tool-density-context").textContent()) ?? "",
			"언제든 펼칠 수 있으며 Port 작업을 끝내면 이전 메뉴 설정으로 돌아갑니다",
			`${label} compact density announces recovery`,
		);
	}
	const expectedTools = [
		["OHB 포트 배치", "OHB"],
		["EQ 포트 행 배치", "EQ"],
		["STK 포트 그룹 배치", "STK"],
		["Station proposal 가져오기", "IMPORT"],
	];
	for (const [toolLabel, compactCaption] of expectedTools) {
		const toolButton = page.getByRole("button", { name: toolLabel, exact: true });
		assertEqual(await toolButton.count(), 1, `${label} exposes ${toolLabel}`);
		await assertLocatorInsideViewport(page, toolButton);
		const bounds = await toolButton.boundingBox();
		assertAtLeast(bounds?.width ?? 0, 44, `${label} ${toolLabel} width`);
		assertAtLeast(bounds?.height ?? 0, 44, `${label} ${toolLabel} height`);
		if (shouldAutoCompact) {
			assertEqual(
				(await toolButton.locator(".tilefab-tool-button-compact-caption").innerText()).trim(),
				compactCaption,
				`${label} ${toolLabel} compact token`,
			);
		}
	}
	if (viewport.width <= 860) {
		for (const cameraLabel of ["화면 확대", "화면 축소", "전체 화면 맞춤"]) {
			const cameraControl = page.getByRole("button", { name: cameraLabel, exact: true });
			await assertLocatorInsideViewport(page, cameraControl);
			const bounds = await cameraControl.boundingBox();
			assertAtLeast(bounds?.width ?? 0, 44, `${label} ${cameraLabel} width`);
			assertAtLeast(bounds?.height ?? 0, 44, `${label} ${cameraLabel} height`);
		}
	} else {
		const fitControl = page.getByRole("button", { name: "전체 보기", exact: true });
		await assertLocatorInsideViewport(page, fitControl);
		const bounds = await fitControl.boundingBox();
		assertAtLeast(bounds?.width ?? 0, 44, `${label} desktop Fit width`);
		assertAtLeast(bounds?.height ?? 0, 44, `${label} desktop Fit height`);
	}
	const buildbar = page.locator(".tilefab-port-buildbar");
	assertEqual(await buildbar.count(), 1, `${label} has one Port buildbar`);
	assertEqual(
		await buildbar.locator(".tilefab-port-authoring-instruction").count(),
		1,
		`${label} has one Port instruction owner`,
	);
	assertEqual(await page.getByTestId("editor-action-hints").count(), 0, `${label} hides hints`);
	assertEqual(await page.getByTestId("guided-build-panel").count(), 0, `${label} hides Guide`);
	assertEqual(await page.locator(".tilefab-inspector").count(), 0, `${label} hides Inspector`);
	const initialLayout = await page.evaluate(() => {
		const navigation = document.querySelector(".tilefab-tools");
		const dock = document.querySelector(".tilefab-port-buildbar");
		const instruction = dock?.querySelector(".tilefab-port-authoring-instruction");
		if (!(navigation instanceof HTMLElement) || !(dock instanceof HTMLElement)) return null;
		const navigationBounds = navigation.getBoundingClientRect();
		const dockBounds = dock.getBoundingClientRect();
		const cameraBounds = document
			.querySelector(".tilefab-camera-controls")
			?.getBoundingClientRect();
		const overlaps = (left, right) =>
			left.left < right.right &&
			left.right > right.left &&
			left.top < right.bottom &&
			left.bottom > right.top;
		return {
			navigationWidth: navigationBounds.width,
			navigationRight: navigationBounds.right,
			dockLeft: dockBounds.left,
			dockRight: dockBounds.right,
			dockTop: dockBounds.top,
			dockHeight: dockBounds.height,
			instructionClientHeight: instruction instanceof HTMLElement ? instruction.clientHeight : 0,
			instructionScrollHeight: instruction instanceof HTMLElement ? instruction.scrollHeight : 0,
			cameraOverlapsNavigation: cameraBounds ? overlaps(cameraBounds, navigationBounds) : false,
			cameraOverlapsDock: cameraBounds ? overlaps(cameraBounds, dockBounds) : false,
			documentOverflow: Math.max(0, document.documentElement.scrollWidth - innerWidth),
		};
	});
	if (!initialLayout) throw new Error(`${label} density layout is unavailable.`);
	assertEqual(initialLayout.documentOverflow, 0, `${label} density document overflow`);
	assertAtMost(initialLayout.dockRight, viewport.width, `${label} Port dock right bound`);
	assertAtLeast(initialLayout.dockLeft, 0, `${label} Port dock left bound`);
	assertAtLeast(initialLayout.dockTop, 0, `${label} Port dock top bound`);
	assertAtMost(
		initialLayout.dockTop + initialLayout.dockHeight,
		viewport.height,
		`${label} Port dock bottom bound`,
	);
	assertAtMost(
		initialLayout.instructionScrollHeight,
		initialLayout.instructionClientHeight + 1,
		`${label} Port instruction is fully readable`,
	);
	assertEqual(
		initialLayout.cameraOverlapsNavigation,
		false,
		`${label} camera controls avoid navigation`,
	);
	assertEqual(initialLayout.cameraOverlapsDock, false, `${label} camera controls avoid Port dock`);
	if (shouldAutoCompact) {
		assertAtMost(initialLayout.navigationWidth, 56, `${label} compact navigation width`);
	} else {
		assertAtLeast(initialLayout.navigationWidth, 156, `${label} expanded navigation width`);
	}
	if (exerciseToggle) {
		const baseline = await readMetrics(page);
		await densityToggle.focus();
		await densityToggle.press("Enter");
		await page.waitForFunction(
			() =>
				document.querySelector(".tilefab-tools")?.getAttribute("data-tool-density") === "expanded",
			undefined,
			{ timeout: 10_000 },
		);
		assertEqual(
			await activityNavigation.getAttribute("data-tool-density-preference"),
			"expanded",
			`${label} local expansion does not rewrite the global preference`,
		);
		assertEqual(
			await activityNavigation.getAttribute("data-tool-density-context"),
			"ordinary-port",
			`${label} local expansion remains inside the Port task`,
		);
		assertEqual(
			await densityToggle.evaluate((element) => element === document.activeElement),
			true,
			`${label} expansion keeps toggle focus`,
		);
		for (const copy of ["OHB Port", "EQ Port 행", "STK Port 그룹", "고급 가져오기"]) {
			assertIncludes(
				await page.locator('.tilefab-editor-activity-tools[data-activity="equip"]').innerText(),
				copy,
				`${label} expanded menu restores ${copy}`,
			);
		}
		assertProjectUnchanged(await readMetrics(page), baseline, `${label} local density expansion`);
		await densityToggle.press("Space");
		await page.waitForFunction(
			() =>
				document.querySelector(".tilefab-tools")?.getAttribute("data-tool-density") === "compact",
			undefined,
			{ timeout: 10_000 },
		);
		assertEqual(
			await densityToggle.evaluate((element) => element === document.activeElement),
			true,
			`${label} collapse keeps toggle focus`,
		);
		assertProjectUnchanged(await readMetrics(page), baseline, `${label} local density collapse`);
		await page.getByTestId("rail-canvas").focus();
		await assertOrdinaryPortKeyboardTargetVisible(page, `${label} density round trip`);
	}
	return Object.freeze(initialLayout);
}

async function assertOrdinaryPortKeyboardTargetVisible(page, label) {
	await page.waitForFunction(
		() => {
			const canvas = document.querySelector('[data-testid="rail-canvas"]');
			const marker = document.querySelector('[data-testid="ordinary-port-keyboard-target"]');
			if (!(canvas instanceof HTMLCanvasElement)) return false;
			if (!(marker instanceof HTMLElement)) return false;
			const screenX = canvas?.dataset.guidedPortKeyboardScreenX ?? "";
			const screenY = canvas?.dataset.guidedPortKeyboardScreenY ?? "";
			const localX = Number(screenX);
			const localY = Number(screenY);
			const rect = canvas.getBoundingClientRect();
			return (
				canvas?.getAttribute("data-port-keyboard-scope") === "ordinary" &&
				marker.dataset.portSlotRow === canvas.dataset.guidedPortKeyboardRow &&
				marker.dataset.portType === canvas.dataset.guidedPortKeyboardType &&
				marker.style.left.length > 0 &&
				marker.style.top.length > 0 &&
				screenX.length > 0 &&
				screenY.length > 0 &&
				Number.isFinite(localX) &&
				Number.isFinite(localY) &&
				localX >= 0 &&
				localX <= rect.width &&
				localY >= 0 &&
				localY <= rect.height &&
				document.elementFromPoint(rect.left + localX, rect.top + localY) === canvas
			);
		},
		undefined,
		{ timeout: 10_000 },
	);
	const visibility = await page.getByTestId("rail-canvas").evaluate((canvas) => {
		const rect = canvas.getBoundingClientRect();
		const marker = document.querySelector('[data-testid="ordinary-port-keyboard-target"]');
		if (!(marker instanceof HTMLElement)) return null;
		const markerRect = marker.getBoundingClientRect();
		const markerLabelRect = marker.querySelector("span")?.getBoundingClientRect() ?? null;
		const localX = Number(canvas.dataset.guidedPortKeyboardScreenX);
		const localY = Number(canvas.dataset.guidedPortKeyboardScreenY);
		const clientX = rect.left + localX;
		const clientY = rect.top + localY;
		const hit = document.elementFromPoint(clientX, clientY);
		return {
			localX,
			localY,
			width: rect.width,
			height: rect.height,
			inside: localX >= 0 && localX <= rect.width && localY >= 0 && localY <= rect.height,
			hitCanvas: hit === canvas,
			marker: {
				row: marker.dataset.portSlotRow ?? "",
				expectedRow: canvas.dataset.guidedPortKeyboardRow ?? "",
				portType: marker.dataset.portType ?? "",
				expectedPortType: canvas.dataset.guidedPortKeyboardType ?? "",
				phase: marker.dataset.phase ?? "",
				label: marker.textContent?.trim() ?? "",
				pointerEvents: getComputedStyle(marker).pointerEvents,
				rect: {
					x: markerRect.x,
					y: markerRect.y,
					width: markerRect.width,
					height: markerRect.height,
				},
				labelRect: markerLabelRect
					? {
							x: markerLabelRect.x,
							y: markerLabelRect.y,
							width: markerLabelRect.width,
							height: markerLabelRect.height,
						}
					: null,
			},
			viewport: { width: innerWidth, height: innerHeight },
			hit:
				hit === null
					? null
					: {
							tagName: hit.tagName,
							className: hit.getAttribute("class") ?? "",
							testId: hit.getAttribute("data-testid") ?? "",
						},
		};
	});
	if (
		!visibility?.inside ||
		!visibility.hitCanvas ||
		visibility.marker.row !== visibility.marker.expectedRow ||
		visibility.marker.portType !== visibility.marker.expectedPortType ||
		visibility.marker.phase.length === 0 ||
		visibility.marker.label.length === 0 ||
		visibility.marker.pointerEvents !== "none" ||
		visibility.marker.rect.x < 0 ||
		visibility.marker.rect.y < 0 ||
		visibility.marker.rect.width < 44 ||
		visibility.marker.rect.height < 44 ||
		visibility.marker.rect.x + visibility.marker.rect.width > visibility.viewport.width ||
		visibility.marker.rect.y + visibility.marker.rect.height > visibility.viewport.height ||
		!visibility.marker.labelRect ||
		visibility.marker.labelRect.x < 0 ||
		visibility.marker.labelRect.y < 0 ||
		visibility.marker.labelRect.x + visibility.marker.labelRect.width > visibility.viewport.width ||
		visibility.marker.labelRect.y + visibility.marker.labelRect.height > visibility.viewport.height
	) {
		throw new Error(`${label} keyboard target is hidden: ${JSON.stringify(visibility)}.`);
	}
}

async function assertOrdinaryEqDockControlsVisible(page, viewport, label) {
	const before = await readMetrics(page);
	const dock = page.locator('.tilefab-port-buildbar[data-port-type="EQ"]');
	const pitchButtons = dock.locator(".tilefab-eq-pitch button");
	const recipeInput = dock.locator(".tilefab-eq-recipe input");
	assertEqual(await pitchButtons.count(), 5, `${label} exposes all five pitch controls`);
	const layout = await dock.evaluate((element) => {
		const rectangle = (target) => {
			const bounds = target.getBoundingClientRect();
			return {
				left: bounds.left,
				right: bounds.right,
				top: bounds.top,
				bottom: bounds.bottom,
				width: bounds.width,
				height: bounds.height,
			};
		};
		return {
			dock: rectangle(element),
			clientWidth: element.clientWidth,
			clientHeight: element.clientHeight,
			scrollWidth: element.scrollWidth,
			scrollHeight: element.scrollHeight,
			scrollLeft: element.scrollLeft,
			scrollTop: element.scrollTop,
			pitchButtons: [...element.querySelectorAll(".tilefab-eq-pitch button")].map((button) => ({
				label: button.textContent?.trim() ?? "",
				...rectangle(button),
			})),
			recipe: rectangle(element.querySelector(".tilefab-eq-recipe")),
			recipeInput: rectangle(element.querySelector(".tilefab-eq-recipe input")),
		};
	});
	assertAtMost(layout.scrollWidth, layout.clientWidth + 1, `${label} horizontal dock overflow`);
	assertAtMost(layout.scrollHeight, layout.clientHeight + 1, `${label} vertical dock overflow`);
	assertEqual(layout.scrollLeft, 0, `${label} initial horizontal scroll`);
	assertEqual(layout.scrollTop, 0, `${label} initial vertical scroll`);
	const assertInsideDock = (bounds, controlLabel) => {
		assertAtLeast(bounds.left, layout.dock.left - 1, `${label} ${controlLabel} left`);
		assertAtMost(bounds.right, layout.dock.right + 1, `${label} ${controlLabel} right`);
		assertAtLeast(bounds.top, layout.dock.top - 1, `${label} ${controlLabel} top`);
		assertAtMost(bounds.bottom, layout.dock.bottom + 1, `${label} ${controlLabel} bottom`);
	};
	for (const bounds of layout.pitchButtons) {
		assertInsideDock(bounds, `${bounds.label} pitch`);
		assertAtLeast(bounds.width, 44, `${label} ${bounds.label} pitch width`);
		assertAtLeast(bounds.height, 44, `${label} ${bounds.label} pitch height`);
	}
	assertInsideDock(layout.recipe, "Recipe");
	assertInsideDock(layout.recipeInput, "Recipe input");
	assertAtLeast(layout.recipe.height, 44, `${label} Recipe target height`);
	assertAtLeast(layout.recipeInput.width, 44, `${label} Recipe input width`);
	await recipeInput.focus();
	assertEqual(
		await recipeInput.evaluate((element) => element === document.activeElement),
		true,
		`${label} Recipe input focus`,
	);
	await page.getByTestId("rail-canvas").focus();
	const after = await readMetrics(page);
	assertProjectUnchanged(after, before, `${label} focus traversal`);
	assertExactStaticFabModelIdentity(after, before, `${label} focus traversal identity`);
	await page.screenshot({
		path: path.join(artifactRoot, `ordinary-eq-controls-${viewport.width}x${viewport.height}.png`),
	});
}

async function assertOrdinaryPortFittedMapClearsControls(page, label) {
	const canvas = page.getByTestId("rail-canvas");
	const encodedBounds = await canvas.getAttribute("data-fitted-map-bounds");
	const bounds = encodedBounds?.split(",").map(Number);
	if (!bounds || bounds.length !== 4 || bounds.some((value) => !Number.isFinite(value))) {
		throw new Error(`${label} has no valid fitted map bounds: ${encodedBounds ?? "missing"}.`);
	}
	assertEqual(
		await canvas.getAttribute("data-fit-port-target-reframed"),
		"false",
		`${label} preserves complete-map Fit without target-only fallback pan`,
	);
	const [minX, minY, maxX, maxY] = bounds;
	const [firstCorner, secondCorner] = await Promise.all([
		screenPointForWorld(page, { x: minX, y: minY }),
		screenPointForWorld(page, { x: maxX + 1, y: maxY + 1 }),
	]);
	const map = {
		left: Math.min(firstCorner.x, secondCorner.x),
		right: Math.max(firstCorner.x, secondCorner.x),
		top: Math.min(firstCorner.y, secondCorner.y),
		bottom: Math.max(firstCorner.y, secondCorner.y),
	};
	const layout = await page.evaluate(() => {
		const toRect = (element) => {
			const bounds = element.getBoundingClientRect();
			return {
				left: bounds.left,
				right: bounds.right,
				top: bounds.top,
				bottom: bounds.bottom,
			};
		};
		const canvas = document.querySelector('[data-testid="rail-canvas"]');
		const marker = document.querySelector('[data-testid="ordinary-port-keyboard-target"]');
		if (!(canvas instanceof HTMLCanvasElement) || !(marker instanceof HTMLElement)) return null;
		const canvasBounds = canvas.getBoundingClientRect();
		const selectors = [
			".tilefab-tools",
			".tilefab-camera-controls",
			".tilefab-pattern-browser",
			".tilefab-blueprint-library",
			".tilefab-guided-build-panel",
			".tilefab-inspector",
			".tilefab-readiness",
			".tilefab-organization-library",
			".tilefab-navigator-panel",
			".tilefab-action-hints",
			".tilefab-buildbar",
			".tilefab-assembly-connector",
		];
		const seen = new Set();
		const obstructions = [];
		for (const selector of selectors) {
			for (const element of document.querySelectorAll(selector)) {
				if (
					!(element instanceof HTMLElement) ||
					element.offsetParent === null ||
					seen.has(element)
				) {
					continue;
				}
				seen.add(element);
				const rect = element.getBoundingClientRect();
				if (
					rect.right <= canvasBounds.left ||
					rect.left >= canvasBounds.right ||
					rect.bottom <= canvasBounds.top ||
					rect.top >= canvasBounds.bottom
				) {
					continue;
				}
				obstructions.push({ selector, rect: toRect(element) });
			}
		}
		const label = marker.querySelector("span");
		return {
			viewport: { width: innerWidth, height: innerHeight },
			canvas: toRect(canvas),
			marker: toRect(marker),
			label: label instanceof HTMLElement ? toRect(label) : null,
			obstructions,
		};
	});
	if (!layout?.label) throw new Error(`${label} cannot resolve its Canvas/current-target layout.`);
	const overlaps = (left, right) =>
		left.left < right.right &&
		left.right > right.left &&
		left.top < right.bottom &&
		left.bottom > right.top;
	const collisions = layout.obstructions
		.map((obstruction) => ({
			selector: obstruction.selector,
			map: overlaps(map, obstruction.rect),
			marker: overlaps(layout.marker, obstruction.rect),
			label: overlaps(layout.label, obstruction.rect),
		}))
		.filter((collision) => collision.map || collision.marker || collision.label);
	if (
		collisions.length > 0 ||
		map.left < layout.canvas.left ||
		map.top < layout.canvas.top ||
		map.right > layout.canvas.right ||
		map.bottom > layout.canvas.bottom ||
		layout.marker.left < layout.canvas.left ||
		layout.marker.top < layout.canvas.top ||
		layout.marker.right > layout.canvas.right ||
		layout.marker.bottom > layout.canvas.bottom ||
		layout.label.left < layout.canvas.left ||
		layout.label.top < layout.canvas.top ||
		layout.label.right > layout.canvas.right ||
		layout.label.bottom > layout.canvas.bottom
	) {
		throw new Error(
			`${label} leaves fitted rail geometry or its current target under editor UI: ${JSON.stringify({ map, layout, collisions })}.`,
		);
	}
	return Object.freeze({ map: Object.freeze(map), layout: Object.freeze(layout) });
}

async function moveOrdinaryPortKeyboardToDirectionalEdge(page, portType, label) {
	const canvas = page.getByTestId("rail-canvas");
	await canvas.focus();
	const initial = await page.evaluate((type) => {
		const canvas = document.querySelector('[data-testid="rail-canvas"]');
		const slots = window.__tileFab?.getEditorModel().portSlotArtifacts[type]?.slots;
		const row = Number(canvas?.getAttribute("data-guided-port-keyboard-row"));
		if (!slots || !Number.isInteger(row) || row < 0 || row >= slots.count) return null;
		let minX = Number.POSITIVE_INFINITY;
		let maxX = Number.NEGATIVE_INFINITY;
		let minY = Number.POSITIVE_INFINITY;
		let maxY = Number.NEGATIVE_INFINITY;
		for (let index = 0; index < slots.count; index += 1) {
			const x = slots.worldPositions[index * 2];
			const y = slots.worldPositions[index * 2 + 1];
			minX = Math.min(minX, x);
			maxX = Math.max(maxX, x);
			minY = Math.min(minY, y);
			maxY = Math.max(maxY, y);
		}
		return {
			row,
			x: slots.worldPositions[row * 2],
			y: slots.worldPositions[row * 2 + 1],
			extents: { minX, maxX, minY, maxY },
		};
	}, portType);
	if (!initial) throw new Error(`${label} cannot resolve the current ${portType} target.`);
	const directions = [
		{ key: "ArrowRight", extent: initial.extents.maxX - initial.x },
		{ key: "ArrowLeft", extent: initial.x - initial.extents.minX },
		{ key: "ArrowDown", extent: initial.extents.maxY - initial.y },
		{ key: "ArrowUp", extent: initial.y - initial.extents.minY },
	].sort((left, right) => right.extent - left.extent);
	const baseline = await readMetrics(page);
	for (const direction of directions) {
		let previousRow = Number(await canvas.getAttribute("data-guided-port-keyboard-row"));
		let trustedPresses = 0;
		let movingBatches = 0;
		for (let batch = 0; batch < 16; batch += 1) {
			for (let index = 0; index < 128; index += 1) {
				await canvas.press(direction.key);
				trustedPresses += 1;
			}
			await page.waitForTimeout(160);
			const nextRow = Number(await canvas.getAttribute("data-guided-port-keyboard-row"));
			if (nextRow === previousRow) {
				if (movingBatches === 0) break;
				await canvas.press(direction.key);
				trustedPresses += 1;
				await page.waitForTimeout(160);
				assertEqual(
					Number(await canvas.getAttribute("data-guided-port-keyboard-row")),
					nextRow,
					`${label} directional edge is stable`,
				);
				await assertOrdinaryPortKeyboardTargetVisible(page, label);
				const navigationMetrics = await readMetrics(page);
				assertProjectUnchanged(navigationMetrics, baseline, `${label} navigation`);
				assertExactStaticFabModelIdentity(navigationMetrics, baseline, `${label} navigation`);
				const current = await page.evaluate((type) => {
					const canvas = document.querySelector('[data-testid="rail-canvas"]');
					const slots = window.__tileFab?.getEditorModel().portSlotArtifacts[type]?.slots;
					const row = Number(canvas?.getAttribute("data-guided-port-keyboard-row"));
					if (!slots || !Number.isInteger(row) || row < 0 || row >= slots.count) return null;
					return {
						row,
						x: slots.worldPositions[row * 2],
						y: slots.worldPositions[row * 2 + 1],
					};
				}, portType);
				if (!current) throw new Error(`${label} lost its current row at the edge.`);
				return Object.freeze({
					key: direction.key,
					row: current.row,
					x: current.x,
					y: current.y,
					trustedPresses,
					movingBatches,
				});
			}
			movingBatches += 1;
			previousRow = nextRow;
		}
		if (movingBatches > 0) {
			throw new Error(`${label} did not reach a stable edge within 2048 trusted keyboard moves.`);
		}
	}
	throw new Error(`${label} has no navigable directional edge from row ${initial.row}.`);
}

async function exerciseOrdinaryPortKeyboardNavigationVisibility(
	page,
	portType,
	label,
	requireCameraPan,
	requireLegalTarget = false,
) {
	const canvas = page.getByTestId("rail-canvas");
	const candidates = await readLegalPortCandidates(page, portType, 4096);
	const initialRow = Number(await canvas.getAttribute("data-guided-port-keyboard-row"));
	const initial =
		candidates.find((candidate) => candidate.row === initialRow) ??
		(await page.evaluate(
			({ type, row }) => {
				const slots = window.__tileFab?.getEditorModel().portSlotArtifacts[type]?.slots;
				if (!slots || row < 0 || row >= slots.count) return null;
				return {
					row,
					x: slots.worldPositions[row * 2],
					y: slots.worldPositions[row * 2 + 1],
				};
			},
			{ type: portType, row: initialRow },
		));
	if (!initial || candidates.length === 0) {
		throw new Error(`${label} keyboard navigation could not resolve initial row ${initialRow}.`);
	}
	const minimumX = Math.min(...candidates.map((candidate) => candidate.x));
	const maximumX = Math.max(...candidates.map((candidate) => candidate.x));
	const minimumY = Math.min(...candidates.map((candidate) => candidate.y));
	const maximumY = Math.max(...candidates.map((candidate) => candidate.y));
	const directions = [
		{ key: "ArrowRight", extent: maximumX - initial.x },
		{ key: "ArrowLeft", extent: initial.x - minimumX },
		{ key: "ArrowDown", extent: maximumY - initial.y },
		{ key: "ArrowUp", extent: initial.y - minimumY },
	].sort((left, right) => right.extent - left.extent);
	const baseline = await readMetrics(page);
	let moved = 0;
	let cameraPanned = false;
	let foundTarget = false;
	const trace = [];
	for (const direction of directions) {
		for (let attempt = 0; attempt < 64; attempt += 1) {
			const beforeRow = await canvas.getAttribute("data-guided-port-keyboard-row");
			await canvas.press(direction.key);
			// Canvas diagnostics publish at a bounded 100 ms cadence; wait beyond that boundary so
			// the asserted row and screen point describe the same rendered keyboard target.
			await page.waitForTimeout(140);
			const afterRow = await canvas.getAttribute("data-guided-port-keyboard-row");
			trace.push({
				key: direction.key,
				beforeRow,
				afterRow,
				legal: await page.getByTestId("ordinary-port-keyboard-target").getAttribute("data-legal"),
				label: await page.getByTestId("ordinary-port-keyboard-target").innerText(),
				hoverRow: await canvas.getAttribute("data-hover-port-slot"),
				screenX: await canvas.getAttribute("data-guided-port-keyboard-screen-x"),
				screenY: await canvas.getAttribute("data-guided-port-keyboard-screen-y"),
				status: await page.locator(".tilefab-statusbar > span[aria-live]").innerText(),
			});
			if (afterRow === beforeRow) break;
			moved += 1;
			assertEqual(
				await canvas.getAttribute("data-hover-port-slot"),
				afterRow,
				`${label} keyboard row owns hover row`,
			);
			await assertOrdinaryPortKeyboardTargetVisible(page, `${label} moved ${direction.key}`);
			const current = await readMetrics(page);
			assertProjectUnchanged(current, baseline, `${label} keyboard navigation`);
			cameraPanned =
				current.cameraOffsetX !== baseline.cameraOffsetX ||
				current.cameraOffsetY !== baseline.cameraOffsetY;
			assertEqual(current.cameraZoom, baseline.cameraZoom, `${label} keyboard navigation zoom`);
			foundTarget =
				(!requireLegalTarget ||
					((await page.getByTestId("ordinary-port-keyboard-target").getAttribute("data-legal")) ===
						"true" &&
						(await page.getByTestId("ordinary-port-keyboard-target").innerText()) ===
							"Port 추가 · ENTER" &&
						afterRow !== String(initialRow))) &&
				(!requireCameraPan || cameraPanned);
			if (foundTarget) break;
		}
		if (foundTarget) break;
	}
	if (moved === 0 || !foundTarget) {
		throw new Error(
			`${label} keyboard navigation could not find a usable directional neighbor: ${JSON.stringify({
				candidateCount: candidates.length,
				initial,
				directions,
				activeElement: await page.evaluate(
					() =>
						document.activeElement?.getAttribute("data-testid") ?? document.activeElement?.tagName,
				),
				status: await page.locator(".tilefab-statusbar > span[aria-live]").innerText(),
				trace,
			})}.`,
		);
	}
	if (requireCameraPan && !cameraPanned) {
		throw new Error(
			`${label} keyboard navigation never crossed the initial visible frame: ${JSON.stringify({
				baseline: {
					x: baseline.cameraOffsetX,
					y: baseline.cameraOffsetY,
					zoom: baseline.cameraZoom,
				},
				trace,
			})}.`,
		);
	}
}

async function assertGuidedProgressLanguage(page, expectation, label) {
	const panel = page.getByTestId("guided-build-panel");
	assertEqual(
		await panel
			.getByText(`GUIDED BUILD · 챕터 ${expectation.chapter} · ADVANCED FAB`, { exact: true })
			.count(),
		1,
		`${label} labels chapter progress`,
	);
	assertEqual(
		await panel
			.getByText(
				`ADVANCED FAB · 미션 ${expectation.chapterMission} · 전체 미션 ${expectation.overallMission}`,
				{ exact: true },
			)
			.count(),
		1,
		`${label} labels chapter and overall mission progress`,
	);
	assertEqual(
		await panel.getByTestId("guided-build-mission-detail").innerText(),
		expectation.work,
		`${label} labels local work progress`,
	);
	const status = panel.locator('[role="status"][aria-live="polite"][aria-atomic="true"]');
	assertEqual(await status.count(), 1, `${label} exposes one atomic live status`);
	assertEqual(
		(await status.innerText()).trim(),
		`전체 미션 ${expectation.overallMission} · ${expectation.title}`,
		`${label} announces only overall mission progress`,
	);
	assertEqual(
		await panel.locator('[aria-live="polite"]').count(),
		1,
		`${label} has no competing polite live region`,
	);
	assertEqual(await panel.getAttribute("aria-live"), null, `${label} panel is not a live ancestor`);
	const progress = panel.getByRole("progressbar", {
		name: "Guided Build 전체 미션 진행률",
	});
	assertEqual(await progress.count(), 1, `${label} exposes one overall progressbar`);
	assertEqual(
		await progress.getAttribute("aria-valuetext"),
		`전체 미션 ${expectation.overallMission} · ${expectation.title}`,
		`${label} accessible progress units`,
	);
	assertEqual(
		await panel.getByText("현재 미션 진행 중", { exact: true }).count(),
		1,
		`${label} removes the duplicate unlabeled mission number`,
	);
	assertEqual(
		await panel.getByText("강조된 작업을 완료해 계속", { exact: true }).count(),
		1,
		`${label} describes the manual continuation gate`,
	);
	assertEqual(
		await panel.getByText("조건 충족 시 자동 진행", { exact: true }).count(),
		0,
		`${label} does not mislabel the manual action as automatic`,
	);
	assertEqual(
		await panel.locator(".tilefab-guided-build-hint").count(),
		0,
		`${label} removes the duplicate command hint owner`,
	);
	assertAtMost(
		await panel.evaluate((element) => element.getBoundingClientRect().height),
		304,
		`${label} keeps the direct-action guide compact`,
	);
}

async function auditGuidedIntermediateWidths(
	page,
	screenshotStem,
	locators,
	expectedTargetId,
	progressExpectation = null,
) {
	for (const viewport of [
		{ width: 760, height: 900, label: "760x900" },
		{ width: 1440, height: 900, label: "1440x900" },
	]) {
		await page.setViewportSize({ width: viewport.width, height: viewport.height });
		await page.evaluate(
			() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
		);
		for (const locator of locators) await assertLocatorInsideViewport(page, locator);
		const target = await assertGuidedPrimaryTarget(
			page,
			expectedTargetId,
			`${screenshotStem} sole owner ${viewport.label}`,
		);
		assertEqual(
			await target.evaluate((element) => element === document.activeElement),
			true,
			`${screenshotStem} focus owner ${viewport.label}`,
		);
		const guidedPicker = page.locator('.tilefab-organization-library[data-guided-picker="true"]');
		for (const selector of [
			".tilefab-navigator-overview",
			".tilefab-organization-filters",
			".tilefab-organization-search",
			".tilefab-organization-selection-toolbar",
			".tilefab-organization-editor",
		]) {
			assertEqual(
				await guidedPicker.locator(selector).isHidden(),
				true,
				`${screenshotStem} hides Expert picker chrome ${selector} at ${viewport.label}`,
			);
		}
		assertEqual(
			await page.locator(".tilefab-tools").isHidden(),
			true,
			`${screenshotStem} suspends the competing Activity rail at ${viewport.label}`,
		);
		assertEqual(
			await page.locator(".tilefab-tools").getAttribute("aria-hidden"),
			"true",
			`${screenshotStem} removes the Activity rail from accessibility at ${viewport.label}`,
		);
		assertEqual(
			await page.locator(".tilefab-tools").getAttribute("inert"),
			"",
			`${screenshotStem} inerts the Activity rail at ${viewport.label}`,
		);
		assertEqual(
			await page.getByTestId("editor-activity-assemble").getAttribute("data-guided-target"),
			null,
			`${screenshotStem} removes the competing Assemble target at ${viewport.label}`,
		);
		assertEqual(
			await page.getByTestId("tilefab-app").getAttribute("data-guided-organization-command"),
			"true",
			`${screenshotStem} publishes one organization command owner at ${viewport.label}`,
		);
		if (progressExpectation) {
			await assertGuidedProgressLanguage(
				page,
				progressExpectation,
				`${screenshotStem} ${viewport.label}`,
			);
		}
		assertAtMost(
			await page.evaluate(() => document.documentElement.scrollWidth),
			viewport.width,
			`${screenshotStem} horizontal overflow ${viewport.label}`,
		);
		await page.screenshot({
			path: path.join(artifactRoot, `${screenshotStem}-${viewport.label}.png`),
			fullPage: true,
		});
	}
	await page.setViewportSize({ width: 390, height: 844 });
	await page.evaluate(
		() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
	);
	const compactTarget = await assertGuidedPrimaryTarget(
		page,
		expectedTargetId,
		`${screenshotStem} sole owner 390x844`,
	);
	assertEqual(
		await compactTarget.evaluate((element) => element === document.activeElement),
		true,
		`${screenshotStem} focus owner 390x844`,
	);
	assertEqual(
		await page.locator(".tilefab-tools").isHidden(),
		true,
		`${screenshotStem} suspends the competing Activity rail at 390x844`,
	);
	assertEqual(
		await page.locator(".tilefab-tools").getAttribute("aria-hidden"),
		"true",
		`${screenshotStem} removes the Activity rail from accessibility at 390x844`,
	);
	assertEqual(
		await page.locator(".tilefab-tools").getAttribute("inert"),
		"",
		`${screenshotStem} inerts the Activity rail at 390x844`,
	);
	if (progressExpectation) {
		await assertGuidedProgressLanguage(page, progressExpectation, `${screenshotStem} 390x844`);
	}
}

async function auditGuidedDuplicatePlacementWidths(
	page,
	screenshotStem,
	placementTarget,
	guidedPanel,
	exit,
) {
	const buildbar = page.getByTestId("rail-buildbar");
	for (const viewport of [
		{ width: 390, height: 720, label: "390x720" },
		{ width: 760, height: 900, label: "760x900" },
		{ width: 1440, height: 900, label: "1440x900" },
	]) {
		await page.setViewportSize({ width: viewport.width, height: viewport.height });
		await page.evaluate(
			() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
		);
		for (const locator of [guidedPanel, buildbar, exit]) {
			await assertLocatorInsideViewport(page, locator);
		}
		const exactOwner = await assertGuidedPrimaryTarget(
			page,
			"canvas:organization-placement",
			`${screenshotStem} exact placement owner ${viewport.label}`,
		);
		assertEqual(
			await exactOwner.evaluate((element) => element === document.activeElement),
			true,
			`${screenshotStem} placement focus ${viewport.label}`,
		);
		assertEqual(
			await page.locator(".tilefab-tools").isHidden(),
			true,
			`${screenshotStem} suspends Activity ${viewport.label}`,
		);
		assertEqual(
			await page.locator(".tilefab-tools").getAttribute("aria-hidden"),
			"true",
			`${screenshotStem} hides Activity from accessibility ${viewport.label}`,
		);
		assertEqual(
			await page.locator(".tilefab-tools").getAttribute("inert"),
			"",
			`${screenshotStem} inerts Activity ${viewport.label}`,
		);
		const exitMetrics = await exit.evaluate((element) => {
			const style = getComputedStyle(element);
			return {
				rectHeight: element.getBoundingClientRect().height,
				height: style.height,
				minHeight: style.minHeight,
				transform: style.transform,
			};
		});
		assertAtLeast(
			exitMetrics.rectHeight,
			44,
			`${screenshotStem} exit action target ${viewport.label} ${JSON.stringify(exitMetrics)}`,
		);
		const placementBounds =
			typeof placementTarget?.boundingBox === "function"
				? await placementTarget.boundingBox()
				: null;
		if (typeof placementTarget?.boundingBox === "function" && !placementBounds) {
			throw new Error(`${screenshotStem} placement target is hidden at ${viewport.label}.`);
		}
		if (placementBounds) {
			assertAtLeast(
				placementBounds.width,
				44,
				`${screenshotStem} placement target width ${viewport.label}`,
			);
			assertAtLeast(
				placementBounds.height,
				44,
				`${screenshotStem} placement target height ${viewport.label}`,
			);
		}
		const placementScreen = placementBounds
			? {
					x: placementBounds.x + placementBounds.width / 2,
					y: placementBounds.y + placementBounds.height / 2,
				}
			: await screenPointForWorld(page, offsetCellCenter(placementTarget));
		const previewHit = await page.evaluate(({ x, y }) => {
			const hit = document.elementFromPoint(x, y);
			return hit?.getAttribute("data-testid") ?? "";
		}, placementScreen);
		const placementTargetTestId = placementBounds
			? await placementTarget.getAttribute("data-testid")
			: null;
		assertEqual(
			previewHit,
			placementTargetTestId ?? "rail-canvas",
			`${screenshotStem} visible preview ${viewport.label}`,
		);
		if (screenshotStem === "guided-bay-duplicate-placement" && viewport.label === "390x720") {
			await assertGuidedOrganizationPlacementMediaTarget(
				page,
				`${screenshotStem} organization marker`,
			);
			const missionHelpButton = page.getByTestId("guided-build-command-help");
			await missionHelpButton.focus();
			await missionHelpButton.press("Enter");
			const missionHelp = page.getByTestId("guided-build-mission-help");
			await missionHelp.waitFor({ state: "visible" });
			await page.waitForFunction(
				() => {
					const panelElement = document.querySelector('[data-testid="guided-build-panel"]');
					const markerElement = document.querySelector(
						'[data-testid="guided-organization-placement-target"]',
					);
					if (!(panelElement instanceof HTMLElement) || !(markerElement instanceof HTMLElement)) {
						return false;
					}
					const panelBounds = panelElement.getBoundingClientRect();
					const markerBounds = markerElement.getBoundingClientRect();
					return (
						panelBounds.bottom <= markerBounds.top ||
						panelBounds.top >= markerBounds.bottom ||
						panelBounds.right <= markerBounds.left ||
						panelBounds.left >= markerBounds.right
					);
				},
				undefined,
				{ timeout: 10_000 },
			);
			assertEqual(
				await missionHelpButton.evaluate((element) => element === document.activeElement),
				true,
				`${screenshotStem} help expansion preserves supporting-control focus`,
			);
			await missionHelpButton.press("Enter");
			await missionHelp.waitFor({ state: "hidden" });
			assertEqual(
				await missionHelpButton.evaluate((element) => element === document.activeElement),
				true,
				`${screenshotStem} help collapse preserves supporting-control focus`,
			);
			await exactOwner.focus();
		}
		if (viewport.width <= 860) {
			const cameraControlsBounds = await page.locator(".tilefab-camera-controls").boundingBox();
			const sourceBounds = parseIntegerTuple(
				await page
					.getByTestId("rail-canvas")
					.getAttribute("data-organization-bundle-source-bounds"),
				4,
				`${screenshotStem} source bounds ${viewport.label}`,
			);
			if (!cameraControlsBounds) {
				throw new Error(`${screenshotStem} camera controls are hidden at ${viewport.label}.`);
			}
			const [minX, minY, maxX, maxY] = sourceBounds;
			const sourceCorners = await Promise.all([
				screenPointForWorld(page, { x: minX, y: minY }),
				screenPointForWorld(page, { x: maxX + 1, y: maxY + 1 }),
			]);
			const sourceScreenBounds = {
				left: Math.min(sourceCorners[0].x, sourceCorners[1].x),
				right: Math.max(sourceCorners[0].x, sourceCorners[1].x),
				top: Math.min(sourceCorners[0].y, sourceCorners[1].y),
				bottom: Math.max(sourceCorners[0].y, sourceCorners[1].y),
			};
			const cameraOverlapsSource = !(
				cameraControlsBounds.x + cameraControlsBounds.width <= sourceScreenBounds.left ||
				cameraControlsBounds.x >= sourceScreenBounds.right ||
				cameraControlsBounds.y + cameraControlsBounds.height <= sourceScreenBounds.top ||
				cameraControlsBounds.y >= sourceScreenBounds.bottom
			);
			assertEqual(
				cameraOverlapsSource,
				false,
				`${screenshotStem} camera controls clear source context ${viewport.label} ${JSON.stringify({ cameraControlsBounds, sourceScreenBounds })}`,
			);
		}
		assertAtMost(
			await page.evaluate(() => document.documentElement.scrollWidth),
			viewport.width,
			`${screenshotStem} horizontal overflow ${viewport.label}`,
		);
		await page.screenshot({
			path: path.join(artifactRoot, `${screenshotStem}-${viewport.label}.png`),
			fullPage: true,
		});
	}
	await page.setViewportSize({ width: 390, height: 844 });
	await page.evaluate(
		() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
	);
	const restoredOwner = await assertGuidedPrimaryTarget(
		page,
		"canvas:organization-placement",
		`${screenshotStem} exact placement owner 390x844`,
	);
	assertEqual(
		await restoredOwner.evaluate((element) => element === document.activeElement),
		true,
		`${screenshotStem} placement focus 390x844`,
	);
	await exit.focus();
	for (const viewport of [
		{ width: 390, height: 720, label: "390x720" },
		{ width: 390, height: 844, label: "390x844" },
		{ width: 760, height: 900, label: "760x900" },
	]) {
		await page.setViewportSize({ width: viewport.width, height: viewport.height });
		await page.evaluate(
			() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))),
		);
		await assertGuidedPrimaryTarget(
			page,
			"canvas:organization-placement",
			`${screenshotStem} supporting-focus owner ${viewport.label}`,
		);
		assertEqual(
			await exit.evaluate((element) => element === document.activeElement),
			true,
			`${screenshotStem} supporting exit focus survives ${viewport.label}`,
		);
	}
	await restoredOwner.focus();
}

async function assertGuidedManualReviewLanguage(guidedPanel, label) {
	assertEqual(
		await guidedPanel.getByText("강조된 검토 작업을 완료해 계속", { exact: true }).count(),
		1,
		`${label} describes the manual review gate`,
	);
	assertEqual(
		await guidedPanel.getByText("조건 충족 시 자동 진행", { exact: true }).count(),
		0,
		`${label} does not describe a manual review as automatic`,
	);
	assertEqual(
		await guidedPanel.locator(".tilefab-guided-build-hint").count(),
		0,
		`${label} leaves action guidance to the focused review control`,
	);
}

