function assertCanonicalAuthoredEquality(firstJson, secondJson) {
	const first = JSON.parse(firstJson);
	const second = JSON.parse(secondJson);
	delete first.manifest.updatedAt;
	delete second.manifest.updatedAt;
	assertEqual(JSON.stringify(second), JSON.stringify(first), "save-load-save authored JSON");
}

function assertEqual(actual, expected, label) {
	if (actual !== expected) {
		throw new Error(
			`${label}: expected ${JSON.stringify(expected)}, received ${JSON.stringify(actual)}`,
		);
	}
}

function assertNotEqual(actual, unexpected, label) {
	if (actual === unexpected) {
		throw new Error(`${label}: expected a value different from ${JSON.stringify(unexpected)}`);
	}
}

function assertIncludes(actual, expectedPart, label) {
	if (!actual.includes(expectedPart)) {
		throw new Error(`${label}: expected ${JSON.stringify(actual)} to include ${expectedPart}`);
	}
}

function assertAtLeast(actual, minimum, label) {
	if (!Number.isFinite(actual) || actual < minimum) {
		throw new Error(`${label}: expected at least ${minimum}, received ${actual}`);
	}
}

function assertAtMost(actual, maximum, label) {
	if (!Number.isFinite(actual) || actual > maximum) {
		throw new Error(`${label}: expected at most ${maximum}, received ${actual}`);
	}
}

function requiredNonNegativeIntegerAttribute(value, label) {
	if (typeof value !== "string" || value.trim() === "") {
		throw new Error(`${label}: expected a present attribute, received ${JSON.stringify(value)}`);
	}
	const parsed = Number(value);
	if (!Number.isFinite(parsed) || !Number.isInteger(parsed) || parsed < 0) {
		throw new Error(`${label}: expected a finite non-negative integer, received ${value}`);
	}
	return parsed;
}

function requiredPositiveIntegerAttribute(value, label) {
	const parsed = requiredNonNegativeIntegerAttribute(value, label);
	assertAtLeast(parsed, 1, label);
	return parsed;
}

function assertDurationTelemetry(value, maximum, label) {
	if (typeof value !== "string" || value.trim() === "") {
		throw new Error(`${label}: expected non-empty telemetry, received ${JSON.stringify(value)}`);
	}
	const milliseconds = Number(value);
	assertAtLeast(milliseconds, 0, label);
	assertAtMost(milliseconds, maximum, label);
}

async function waitForProjectOperation(page, operation) {
	await page.waitForFunction(
		(expected) => document.querySelector(".tilefab-app")?.dataset.projectOperation === expected,
		operation,
		{ timeout: 10_000 },
	);
}

async function closeBrowserResource(resource, label) {
	if (!resource) return;
	let timeout;
	try {
		await Promise.race([
			resource.close(),
			new Promise((_, reject) => {
				timeout = setTimeout(
					() => reject(new Error(`${label} close timed out after 5 seconds.`)),
					5_000,
				);
			}),
		]);
	} catch (error) {
		console.warn(error instanceof Error ? error.message : String(error));
		const emergencyKill = browserEmergencyKillers.get(resource);
		if (emergencyKill) {
			let emergencyTimeout;
			try {
				await Promise.race([
					emergencyKill(),
					new Promise((_, reject) => {
						emergencyTimeout = setTimeout(
							() => reject(new Error(`${label} emergency close timed out after 2 seconds.`)),
							2_000,
						);
					}),
				]);
				console.warn(`${label} was force-closed after the graceful timeout.`);
			} catch (emergencyError) {
				console.warn(
					emergencyError instanceof Error ? emergencyError.message : String(emergencyError),
				);
			} finally {
				clearTimeout(emergencyTimeout);
			}
		}
	} finally {
		clearTimeout(timeout);
	}
}

async function launchBrowserWithRetry() {
	let lastError;
	for (let attempt = 0; attempt < 2; attempt++) {
		try {
			const launchedBrowser = await chromium.launch({
				executablePath: chromePath,
				headless: true,
				timeout: 20_000,
			});
			const createNativeContext = launchedBrowser.newContext.bind(launchedBrowser);
			Object.defineProperty(launchedBrowser, "newContext", {
				configurable: true,
				value: async (...argumentsList) => {
					const context = await createNativeContext(...argumentsList);
					await context.addInitScript(() => {
						for (const key of ["showOpenFilePicker", "showSaveFilePicker", "showDirectoryPicker"]) {
							Object.defineProperty(globalThis, key, {
								value: undefined,
								writable: false,
								configurable: true,
							});
						}
					});
					return context;
				},
			});
			// playwright-core does not expose its local ChildProcess publicly. Keep only the
			// implementation-provided kill closure so a timed-out acceptance close cannot retain a
			// multi-GB Chrome tree. This remains scoped to the exact browser launched above.
			const browserImplementation = launchedBrowser._connection?.toImpl?.(launchedBrowser);
			const browserProcess = browserImplementation?.options?.browserProcess;
			if (typeof browserProcess?.kill === "function") {
				browserEmergencyKillers.set(launchedBrowser, () => {
					const childProcess = browserProcess.process;
					if (!childProcess || childProcess.exitCode !== null) return Promise.resolve();
					return new Promise((resolve, reject) => {
						const finish = () => resolve();
						childProcess.once("exit", finish);
						childProcess.once("error", finish);
						Promise.resolve(browserProcess.kill()).catch(reject);
					});
				});
			}
			return launchedBrowser;
		} catch (error) {
			lastError = error;
			await new Promise((resolve) => setTimeout(resolve, 250));
		}
	}
	throw lastError;
}

async function stopPreviewServer(child) {
	if (child.exitCode !== null) return;
	const exited = new Promise((resolve) => {
		child.once("exit", resolve);
		child.once("error", resolve);
	});
	child.kill("SIGTERM");
	await Promise.race([exited, new Promise((resolve) => setTimeout(resolve, 2_000))]);
	if (child.exitCode === null) child.kill("SIGKILL");
}

function startPreviewServer() {
	const vite = path.join(root, "node_modules", "vite", "bin", "vite.js");
	const serverMode = process.env.OPENFAB_AUTHORING_DEV_SERVER === "1" ? "dev" : "preview";
	const serverArguments =
		serverMode === "dev"
			? [vite, "--host", host, "--port", String(port), "--strictPort"]
			: [vite, "preview", "--host", host, "--port", String(port), "--strictPort"];
	const child = spawn(process.execPath, serverArguments, {
		cwd: root,
		stdio: ["ignore", "ignore", "pipe"],
	});
	child.stderr.on("data", (chunk) => process.stderr.write(chunk));
	return child;
}

async function waitForServer(url) {
	const deadline = Date.now() + 10_000;
	while (Date.now() < deadline) {
		try {
			const response = await fetch(url);
			if (response.ok) return;
		} catch {
			// Preview is still starting.
		}
		await new Promise((resolve) => setTimeout(resolve, 100));
	}
	throw new Error(`Static FAB authoring preview did not start at ${url}.`);
}

async function resolveChromePath() {
	const candidates = [
		process.env.OPENFAB_CHROME_BIN,
		"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
		"/Applications/Chromium.app/Contents/MacOS/Chromium",
		"/usr/bin/google-chrome",
		"/usr/bin/chromium",
	].filter(Boolean);
	for (const candidate of candidates) {
		try {
			await access(candidate);
			return candidate;
		} catch {
			// Try the next platform path.
		}
	}
	throw new Error("Chrome was not found. Set OPENFAB_CHROME_BIN to its executable path.");
}
